#include <iostream>
#include <optional>
#include <variant>
#include <string>

int main() {
    const std::optional<int> port = 8080;
    std::variant<int, std::string> response = std::string{"ready"};
    std::cout << port.value_or(80) << ':' << std::get<std::string>(response) << '\n';
}
